//! `shape` generated by `mlirformat tblgen` (`shape.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "shape.gen.rs"]
mod shape;

#[test]
fn shape_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<shape::Shape>();
    common::Fixtures::check_dialect(&opt, "shape");
}
